fn temp_repo(label: &str) -> PathBuf {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("time went backwards")
        .as_nanos();
    std::env::temp_dir().join(format!(
        "adl-runtime-v2-cli-{label}-{}-{nanos}",
        std::process::id()
    ))
}

